import re
def grep(text, pat, w=350, maxn=6):
    out=[]
    for m in re.finditer(pat, text, flags=re.I):
        s=max(0,m.start()-w); e=min(len(text), m.end()+w)
        out.append(text[s:e].replace("\n"," "))
        if len(out)>=maxn: break
    return out

